# 콘텐츠 유형별 가중치로 모델 고르기 (가상 측정값)
models = {  # 품질(사람 선호 승률), 1초당 비용(원), 생성 지연(초)
    "상용A": (0.82, 120, 95),
    "상용B": (0.74, 45, 60),
    "오픈C": (0.66, 18, 240),
}
weights = {  # 품질, 비용, 지연
    "장 마감 뉴스 요약(빨리)": (0.4, 0.2, 0.4),
    "브랜드 광고(품질)":       (0.8, 0.1, 0.1),
    "종목 설명 대량 제작":     (0.3, 0.6, 0.1),
}
def scale(v, lo, hi, higher_better):
    x = (v - lo) / (hi - lo)
    return x if higher_better else 1 - x
q = [m[0] for m in models.values()]; c = [m[1] for m in models.values()]; l = [m[2] for m in models.values()]
for kind, (wq, wc, wl) in weights.items():
    score = {n: wq*scale(a, min(q), max(q), True) + wc*scale(b, min(c), max(c), False) + wl*scale(d, min(l), max(l), False)
             for n, (a, b, d) in models.items()}
    best = max(score, key=score.get)
    print(kind, "→", best, {k: round(v, 2) for k, v in score.items()})

# 출력
# 장 마감 뉴스 요약(빨리) → 상용B {'상용A': 0.72, '상용B': 0.75, '오픈C': 0.2}
# 브랜드 광고(품질) → 상용A {'상용A': 0.88, '상용B': 0.57, '오픈C': 0.1}
# 종목 설명 대량 제작 → 상용B {'상용A': 0.38, '상용B': 0.69, '오픈C': 0.6}
